before.script:
export default {
  data() {
    return {
      loading: false,
      error: null,
      rooms: []
    }
  },
  methods: {
    async checkAvailability() {
      this.loading = true
      try {
        const response = await this.$frappe.call({
          method: 'logistay.api.check_availability',
          args: { date: this.selectedDate }
        })
        this.rooms = response.message
      } catch (err) {
        this.error = err
        console.error('Error:', err)
      } finally {
        this.loading = false
      }
    }
  }
}

example_3_composable.code:
import { createResource } from 'frappe-ui'

// مشاركة بيانات السائق عبر جميع المكونات
let driverProfileResource = null

export function useDriverProfile() {
  // Singleton pattern - إنشاء مرة واحدة فقط
  if (!driverProfileResource) {
    driverProfileResource = createResource({
      url: 'logistay.api.driver.get_profile',
      cache: true,
      auto: true
    })
  }

  return {
    profile: driverProfileResource,
    reload: () => driverProfileResource.reload(),
    update: (data) => driverProfileResource.submit(data)
  }
}

// الاستخدام في أي component:
